import re

# Extract the instances from context
lines = context.strip().split('\n')
instances = []

for line in lines:
    if '||' in line and 'Date:' in line:
        instances.append(line)

print(f"Found {len(instances)} instances")
for i, inst in enumerate(instances):
    print(f"{i+1}: {inst[:60]}...")

# Find June instances
june_instances = []
for inst in instances:
    if 'Jun ' in inst:
        june_instances.append(inst)

print(f"June instances: {len(june_instances)}")
for j in june_instances:
    print(j)
